for i,r in enumerate(log_rows):
    m=r.get('message',{})
    if m.get('role')=='assistant' and any(isinstance(c,dict) and isinstance(c.get('text'),str) and c['text'].startswith('{"action": "submit"') for c in m.get('content',[])):
        texts=[c['text'] for c in m['content'] if isinstance(c,dict) and isinstance(c.get('text'),str)]
        print(i, texts[-1][:250])

demo_pairs=[]
for text in user_texts:
    for m in re.finditer(r'Demo pair \d+ input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \d+ output \(\d+x\d+\):\n(.*?)(?=\n\n(?:Same instance|Wrong attempts|$))', text, re.S):
        h,w=int(m.group(1)),int(m.group(2))
        ain=[[int(x) for x in line.split()] for line in m.group(3).splitlines() if line.strip()]
        out=[[int(x) for x in line.split()] for line in m.group(4).splitlines() if line.strip()]
        if len(ain)==h and all(len(r)==w for r in ain) and len(out)==h and all(len(r)==w for r in out): demo_pairs.append((ain,out))
print('demo pairs parsed',len(demo_pairs),[(len(a),len(a[0]),set(v for row in a for v in row),set(v for row in b for v in row)) for a,b in demo_pairs])

def transform(grid):
    colors={v for row in grid for v in row}
    other=next(c for c in colors if c != 5)
    return [[other if v==5 else 0 for v in row] for row in grid]
print([transform(a)==b for a,b in demo_pairs])
